import json,pathlib,html,csv,collections,hashlib
ROOT=pathlib.Path(__file__).resolve().parents[2];OUT=pathlib.Path(__file__).parent
read=lambda p:json.loads(p.read_text())
before=read(OUT/'online-before.json');catalog=read(ROOT/'docs/aso/search-localizations.json');copy=read(ROOT/'docs/aso/ios-description-localizations.json'); protected=read(OUT/'protected-paragraphs.json')
ver=next(v for v in before['versions'] if v['version']['attributes']['platform']=='IOS')
old={x['attributes']['locale']:x['attributes'] for x in ver['localizations']}
info=next(v for v in before['appInfos'] if v['appInfo']['id']=='988607e7-fe9f-45ad-9432-86fca303d591')
oldinfo={x['attributes']['locale']:x['attributes'] for x in info['localizations']}
samples=read(OUT/'market-search-samples.json')+read(ROOT/'reports/aso-28-languages-20261011/market-search-samples.json')
rows=[];diff=[]
for locale,row in catalog['localizations'].items():
 fields={k:row[k] for k in ['name','subtitle','keywords']};fields['description']=copy['localizations'][locale]['description']
 prior={**{k:oldinfo[locale][k] for k in ['name','subtitle']},**{k:old[locale][k] for k in ['keywords','description']}}
 changed=[k for k in fields if fields[k]!=prior[k]]
 for field in changed:diff.append({'locale':locale,'field':field,'before':prior[field],'after':fields[field]})
 evidence=[s for s in samples if s['locale']==locale]
 protection=next(p for p in protected if p['locale']==locale)
 for p in protection['sourceParagraphs']:
  adjustment=next((e for e in protection['permittedGrammarEdits'] if e['before']==p),None)
  assert (adjustment['after'] if adjustment else p) in fields['description'],(locale,'protected text missing')
 rows.append({'locale':locale,'label':row['label'],'language':row['language'],'market':row['market'],'before':prior,'after':fields,'changed':changed,'review':copy['localizations'][locale]['reviewNote'],'queries':row['searchQueries'],'source':row['terminologySource'],'evidence':evidence,'limits':{'name':len(fields['name']),'subtitle':len(fields['subtitle']),'keywordsBytes':len(fields['keywords'].encode()),'description':len(fields['description'])},'otherFields':'推广文本保留为空；版本更新说明、支持/营销 URL 保持原值。订阅、隐私与使用限制保留；匈牙利语两处仅修正品牌前冠词和后缀。'})
(OUT/'intended-copy-diff.json').write_text(json.dumps(diff,ensure_ascii=False,indent=2)+'\n')
(OUT/'language-review.json').write_text(json.dumps(rows,ensure_ascii=False,indent=2)+'\n')
with (OUT/'localizations.csv').open('w',newline='',encoding='utf-8-sig') as f:
 w=csv.writer(f);w.writerow(['locale','语言','标题','副标题','关键词','完整说明','逐语言审查','变更字段','关键词字节','说明字符'])
 for r in rows:w.writerow([r['locale'],r['label'],*[r['after'][k] for k in ['name','subtitle','keywords','description']],r['review'],','.join(r['changed']),r['limits']['keywordsBytes'],r['limits']['description']])
receipt=read(OUT/'completion-receipt.json') if (OUT/'completion-receipt.json').exists() else None
state='已保存草稿并回读 · 未提交审核' if receipt and receipt['passed'] else '待写入的完整审查稿'
counts=collections.Counter(d['field'] for d in diff)
page='''<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>CastReader · 29 个 iOS 商店条目审查</title><style>
:root{color-scheme:light;--ink:#192d2a;--muted:#61706c;--line:#d9e1dc;--green:#166b53}*{box-sizing:border-box}body{margin:0;background:#f5f7f2;color:var(--ink);font:15px/1.65 -apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif}header{padding:36px max(24px,calc((100vw - 1220px)/2));background:#173e35;color:#fff}h1{font-size:30px;line-height:1.25;margin:12px 0}header p{max-width:1000px;color:#d8e7df}.tag{display:inline-block;border:1px solid #7ba695;border-radius:20px;padding:3px 12px;font-size:12px}.wrap{max-width:1268px;margin:auto;padding:24px}.metrics{display:grid;grid-template-columns:repeat(4,1fr);gap:12px;margin-bottom:20px}.metric{background:white;border:1px solid var(--line);padding:16px;border-radius:12px}.metric b{font-size:28px;display:block}.toolbar{display:flex;gap:12px;flex-wrap:wrap;position:sticky;top:0;background:#f5f7f2;padding:14px 0;z-index:1}select,input,button{font:inherit;border:1px solid #b4c8bd;background:white;border-radius:8px;padding:10px;max-width:100%}input{flex:1;min-width:220px}button{cursor:pointer}article{background:white;border:1px solid var(--line);border-radius:14px;padding:24px;margin:16px 0}h2{font-size:24px;margin:0 0 8px}h3{font-size:14px;color:var(--muted);margin:20px 0 6px}.note{background:#eef5ee;border-left:3px solid var(--green);padding:12px 16px}.grid{display:grid;grid-template-columns:1fr 1fr;gap:24px}pre{white-space:pre-wrap;overflow-wrap:anywhere;font:inherit;margin:8px 0;color:var(--ink)}.title{font-size:22px;font-weight:600}.sub{font-size:17px}.keywords{background:#f3f5f1;border-radius:8px;padding:12px}small,.muted{color:var(--muted)}a{color:#12654f}details{margin:14px 0}summary{cursor:pointer;font-weight:600}.checks{border-top:1px solid var(--line);padding-top:10px;font-size:13px;color:var(--muted)}.hidden{display:none}.desc{font-size:15px;line-height:1.8}.pill{display:inline-block;background:#eef1ed;padding:2px 8px;border-radius:12px;margin:2px;font-size:12px}@media(max-width:760px){.grid{grid-template-columns:1fr}.metrics{grid-template-columns:1fr 1fr}h1{font-size:25px}.wrap{padding:16px}article{padding:18px}}@media print{.toolbar,button{display:none}article{break-inside:avoid}details>div{display:block}header{background:white;color:black}header p{color:black}}
</style><header><span class="tag">iOS 1.2.49 · __STATE__</span><h1>每种语言，都从用户想做的事开始</h1><p>29 个商店条目的名称、副标题、关键词与完整应用说明。全球应用支持 28 种语言；其中 27 种可对应 ASC，另保留繁体中文与墨西哥西语。菲律宾语没有独立商店栏位。这里的文案已逐条审查，检索样本不代表搜索量或排名保证。</p></header><main class="wrap"><div class="metrics"><div class="metric"><b>29</b>完整说明重写</div><div class="metric"><b>__TITLES__ / __SUBS__</b>标题 / 副标题进一步调整</div><div class="metric"><b>__KEYWORDS__</b>关键词组进一步调整</div><div class="metric"><b>__SAMPLES__</b>两轮 Apple Search API 样本</div></div><div class="note">首屏先讲内容与使用收益，再说明原文朗读、AI 解读与输入方式。订阅、克隆音色额度、隐私、YouTube 限制均保留。简体中文明确国际版 28 种、中国地区服务 9 种语言。名称和副标题属于 iOS / Mac 共享 App Info；Mac 完整说明未改。</div><div class="toolbar"><select id="locale"><option value="">全部 29 个条目</option></select><input id="search" aria-label="搜索" placeholder="搜索语言、关键词或审查结论"><button id="toggle">仅看标题或关键词有变化</button></div><div id="cards"></div><article><h2>证据与后续验证</h2><p>这是基于 Apple 本地化术语、当地公开检索结果与产品功能的编辑审查，不是母语用户访谈或真人逐字审校。没有购买或假设搜索量。低返回数不等于低需求；App Store 的真实结果还受设备、系统与用户状态影响。</p><p>Filipino：应用语言保留；ASC 无独立栏位，不伪造 locale。菲律宾的 Filipino text to speech 英文查询有相关结果，本地 basahin nang malakas 样本未返回结果，仍不能推断需求为零。商店回退受支持 locale、地区和用户语言设置影响，不能保证所有菲律宾用户看到同一条目。</p><p>正式上线后，以生效日为起点记录 14 / 28 天的地区数据：搜索展示、产品页访问、首次下载与转化。App Store Search 来源包含 Apple Ads；有投放时不能把它全部称为自然流量。描述主要承担解释产品、匹配意图和转化，不把堆砌词频当作排名机制。此次未创建定时任务。</p><p><a href="https://developer.apple.com/app-store/search/">Apple 搜索说明</a> · <a href="https://developer.apple.com/app-store/product-page/">产品页指南</a> · <a href="https://developer.apple.com/help/app-store-connect/reference/app-information/platform-version-information">字段与长度限制</a> · <a href="https://developer.apple.com/help/app-store-connect/reference/app-information/app-store-localizations/">支持的商店本地化</a> · <a href="https://developer.apple.com/cn/help/app-store-connect-analytics/acquisition/acquisition">获取来源定义</a></p></article></main><script id="data" type="application/json">__DATA__</script><script>
const rows=JSON.parse(document.getElementById('data').textContent),el=document.getElementById('cards'),locale=document.getElementById('locale'),query=document.getElementById('search');let changedOnly=false;const esc=x=>String(x).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
for(const r of rows){const o=document.createElement('option');o.value=r.locale;o.textContent=r.label+' · '+r.locale;locale.append(o)}
function render(){const q=query.value.toLocaleLowerCase();el.innerHTML=rows.filter(r=>(!locale.value||r.locale===locale.value)&&(!q||JSON.stringify(r).toLocaleLowerCase().includes(q))&&(!changedOnly||r.changed.some(k=>k!=='description'))).map(r=>`<article><h2>${esc(r.label)} <small>${esc(r.locale)}</small></h2><div>${r.changed.map(k=>`<span class="pill">${esc(k)} 已调整</span>`).join('')}</div><p class="note">${esc(r.review)}</p><div class="grid"><div><h3>标题</h3><pre class="title" dir="auto">${esc(r.after.name)}</pre><h3>副标题</h3><pre class="sub" dir="auto">${esc(r.after.subtitle)}</pre><h3>关键词 · ${r.limits.keywordsBytes}/100 字节</h3><pre class="keywords" dir="auto">${esc(r.after.keywords)}</pre><p><small>标题 ${r.limits.name}/30 · 副标题 ${r.limits.subtitle}/30 · 说明 ${r.limits.description}/4000</small></p><h3>检索意图候选</h3><p dir="auto">${r.queries.map(esc).join(' · ')}</p><a href="${esc(r.source)}">Apple 本地化术语参考</a><details><summary>查看修改前的标题、关键词与说明</summary><div><pre dir="auto">${esc(r.before.name)}\n${esc(r.before.subtitle)}\n\n${esc(r.before.keywords)}\n\n${esc(r.before.description)}</pre></div></details><details><summary>查看该市场检索样本</summary><div>${r.evidence.map(e=>`<p><a href="${esc(e.url)}">${esc(e.term)}</a> · 返回 ${e.resultCount??'失败'} 条<br><small>${(e.sample||[]).slice(0,3).map(s=>esc(s.name)).join(' / ')}</small></p>`).join('')}<small>返回顺序不是 iPhone App Store 实际排名。未获得搜索量。</small></div></details></div><div><h3>完整应用说明</h3><pre class="desc" dir="auto">${esc(r.after.description)}</pre></div></div><p class="checks">${esc(r.otherFields)}</p></article>`).join('')}
locale.onchange=query.oninput=render;document.getElementById('toggle').onclick=e=>{changedOnly=!changedOnly;e.target.textContent=changedOnly?'显示全部条目':'仅看标题或关键词有变化';render()};render();
</script></html>'''
for key,value in {'STATE':state,'TITLES':counts['name'],'SUBS':counts['subtitle'],'KEYWORDS':counts['keywords'],'SAMPLES':len(samples),'DATA':json.dumps(rows,ensure_ascii=False).replace('<','\\u003c')}.items():page=page.replace('__'+key+'__',str(value))
